        (b"bcd", 22),
        (b"cde", 33),
        (b"def", 44),
        (b"efg", 55),
    ]);

assert_eq!(const { MAP.const_get_with_index(b"def") }, Some((3, &44)));

assert_eq!(const { MAP.const_get_with_index(b"dng") }, None);
```

